//! The bridge of Ledger.Entry: the exports its C# façade calls (CodeCoreMorph, D-84).
use std::ffi::c_char;
use std::sync::Arc;

use super::ccm::{self, ccm_status, Handle};
use crate::entry::Entry;

/// `Entry`'s hierarchy (Entry, Sale, Refund, PartialRefund, Note) shares its root's handle type.
pub struct ledger_Entry(());

impl Handle for ledger_Entry {
    type Target = dyn Entry;
}

#[unsafe(no_mangle)]
pub extern "C" fn ledger_Entry_release(handle: *mut ledger_Entry) {
    ccm::release(handle);
}

#[unsafe(no_mangle)]
pub extern "C" fn ledger_Entry_key(handle: *const ledger_Entry) -> u64 {
    ccm::key(handle)
}

/// An entry of a C# class deriving from Entry: Entry is a trait, so its protected constructor
/// makes one of these.
struct CSharpEntry {
    memo: String,
}

impl Entry for CSharpEntry {
    fn memo(&self) -> &str {
        &self.memo
    }
}

/// Entry's protected constructor: the entry of a C# class deriving from Entry.
#[unsafe(no_mangle)]
pub extern "C" fn ledger_Entry_new(memo: *const c_char, result: *mut *mut ledger_Entry) -> ccm_status {
    ccm::guard(|| {
        let entry: Arc<dyn Entry> = Arc::new(CSharpEntry { memo: ccm::str_in(memo, "memo")? });
        ccm::put(result, ccm::to_handle::<ledger_Entry>(entry));
        Ok(())
    })
}

#[unsafe(no_mangle)]
pub extern "C" fn ledger_Entry_memo(self_: *const ledger_Entry, result: *mut *mut c_char) -> ccm_status {
    ccm::guard(|| {
        ccm::out_str(result, ccm::from_handle(self_)?.memo());
        Ok(())
    })
}

