use super::ccm::{self, ccm_decimal, ccm_status, Handle};
use crate::invoice::Invoice;

pub struct ledger_Invoice(());

impl Handle for ledger_Invoice {
    type Target = Invoice;
}

#[unsafe(no_mangle)]
pub extern "C" fn ledger_Invoice_release(handle: *mut ledger_Invoice) {
