}

#[unsafe(no_mangle)]
pub extern "C" fn ledger_Invoice_key(handle: *const ledger_Invoice) -> u64 {
    ccm::key(handle)
}

/// A null memo is the empty string: C# concatenates a null memo as one.
#[unsafe(no_mangle)]
pub extern "C" fn ledger_Invoice_new(
    memo: *const c_char,
    amount: ccm_decimal,
    days: i32,
    result: *mut *mut ledger_Invoice,
) -> ccm_status {
