//! The bridge of Ledger.Refund: the exports its C# façade calls (CodeCoreMorph, D-84).
use std::ffi::c_char;
use std::sync::Arc;

use super::ccm::{self, ccm_decimal, ccm_status};
use super::entry::ledger_Entry;
use crate::entry::Entry;
use crate::refund::Refund;
use codecoremorph_runtime::Exception;

#[unsafe(no_mangle)]
pub extern "C" fn ledger_Refund_new(
    memo: *const c_char,
    amount: ccm_decimal,
    result: *mut *mut ledger_Entry,
) -> ccm_status {
    ccm::guard(|| {
        let refund: Arc<dyn Entry> = Arc::new(Refund::new(ccm::str_in(memo, "memo")?, ccm::dec(amount)?));
        ccm::put(result, ccm::to_handle::<ledger_Entry>(refund));
        Ok(())
    })
}

/// A PartialRefund's too: it is a Refund in C#.
#[unsafe(no_mangle)]
pub extern "C" fn ledger_Refund_amount(self_: *const ledger_Entry, result: *mut ccm_decimal) -> ccm_status {
    ccm::guard(|| {
        let entry: &dyn std::any::Any = &**ccm::from_handle(self_)?;
        let amount = if let Some(refund) = entry.downcast_ref::<Refund>() {
            refund.amount()
        } else {
            return Err(Exception::invalid_operation("the entry is not a refund"));
        };
        ccm::put(result, ccm::dec_out(amount));
        Ok(())
    })
}

