/// C#'s `dynamic item` of Labels.Line, closed over the types the solution passes it (D-88).
#[derive(Clone)]
pub enum LabelItem {
    Sale(Arc<Sale>),
    Refund(Arc<Refund>),
    PartialRefund(Arc<PartialRefund>),
    Note(Arc<Note>),
    Invoice(Arc<Invoice>),
}

pub struct Labels;

impl Labels {
    /// Anything with a memo and an amount, as a line of text.
    pub fn line(item: &LabelItem) -> Result<String> {
        // C#'s item.Memo + ": " + item.Amount.ToString("0.00", CultureInfo.InvariantCulture).
        let (memo, amount) = match item {
            LabelItem::Sale(x) => (x.memo(), x.amount()),
            LabelItem::Refund(x) => (x.memo(), x.amount()),
            LabelItem::PartialRefund(x) => (x.memo(), x.amount()),
            LabelItem::Invoice(x) => (x.memo(), x.amount()),
            LabelItem::Note(_) => {
                // item.Memo binds (Entry.Memo); item.Amount binds nothing.
                return Err(Exception::runtime_binder(
                    "'Ledger.Note' does not contain a definition for 'Amount'",
                ));
            }
        };
        Ok(format!("{memo}: {}", amount.to_fixed(2)))
    }
