use std::sync::{Arc, Mutex, MutexGuard};

use codecoremorph_runtime::{Decimal, Result};

use crate::invoice::Invoice;
use crate::labels::{LabelItem, Labels};
use crate::sale::Sale;

fn lock<T>(m: &Mutex<T>) -> MutexGuard<'_, T> {
    m.lock().unwrap_or_else(|poisoned| poisoned.into_inner())
}

/// An element of C#'s List<dynamic> of Journal: the types its Record overloads add (D-88).
#[derive(Clone)]
pub enum JournalLine {
    Sale(Arc<Sale>),
    Invoice(Arc<Invoice>),
}

/// Sales and invoices, in the order they came.
#[derive(Default)]
pub struct Journal {
    lines: Mutex<Vec<JournalLine>>,
}

impl Journal {
    pub fn new() -> Journal {
        Journal::default()
    }

    pub fn record_sale(&self, sale: Arc<Sale>) {
        lock(&self.lines).push(JournalLine::Sale(sale));
    }

    pub fn record_invoice(&self, invoice: Arc<Invoice>) {
        lock(&self.lines).push(JournalLine::Invoice(invoice));
    }

    pub fn count(&self) -> i32 {
        lock(&self.lines).len() as i32
    }

    pub fn sum(&self) -> Result<Decimal> {
        let mut sum = Decimal::from(0);
        for line in lock(&self.lines).iter() {
            // C#'s sum += line.Amount: Sale.Amount or Invoice.Amount, decimal addition.
            let amount = match line {
                JournalLine::Sale(sale) => sale.amount(),
                JournalLine::Invoice(invoice) => invoice.amount(),
            };
            sum = sum.checked_add(amount)?;
        }
        Ok(sum)
    }

    pub fn last(&self) -> Result<String> {
        let last = lock(&self.lines).last().cloned();
        match last {
            None => Ok(String::new()),
            // C#'s Labels.Line(lines[^1]): Line(dynamic) with the element's own type.
            Some(JournalLine::Sale(sale)) => Labels::line(&LabelItem::Sale(sale)),
            Some(JournalLine::Invoice(invoice)) => Labels::line(&LabelItem::Invoice(invoice)),
        }
    }
}

