//! The Rust of Ledger.Tally, ported from C# (CodeCoreMorph, D-84).
use std::sync::{Mutex, MutexGuard};

use codecoremorph_runtime::{Decimal, Result};

fn lock<T>(m: &Mutex<T>) -> MutexGuard<'_, T> {
    m.lock().unwrap_or_else(|poisoned| poisoned.into_inner())
}

/// C#'s `dynamic total` of Tally: an int until a decimal comes in (D-88).
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum TallyTotal {
    Int(i32),
    Decimal(Decimal),
}

/// A running count: whole units until an amount comes in.
pub struct Tally {
    total: Mutex<TallyTotal>,
}

impl Default for Tally {
    fn default() -> Self {
        Tally::new()
    }
}

impl Tally {
    pub fn new() -> Tally {
        Tally { total: Mutex::new(TallyTotal::Int(0)) }
    }

    pub fn add_units(&self, units: i32) -> Result<()> {
        // C#'s total += units: an int stays an int (wrapping, as unchecked C# does); a decimal
        // stays a decimal.
        let mut total = lock(&self.total);
        *total = match *total {
            TallyTotal::Int(whole) => TallyTotal::Int(whole.wrapping_add(units)),
            TallyTotal::Decimal(amount) => TallyTotal::Decimal(amount.checked_add(Decimal::from(units))?),
        };
        Ok(())
    }

    pub fn add_amount(&self, amount: Decimal) -> Result<()> {
        // C#'s total += amount: decimal addition, whichever the total was.
        let mut total = lock(&self.total);
        let before = match *total {
            TallyTotal::Int(whole) => Decimal::from(whole),
            TallyTotal::Decimal(d) => d,
        };
        *total = TallyTotal::Decimal(before.checked_add(amount)?);
        Ok(())
    }

    pub fn total(&self) -> TallyTotal {
        *lock(&self.total)
    }
}

