use std::any::Any;

use codecoremorph_runtime::{Decimal, Result};

use crate::entry::Entry;
use crate::partial_refund::PartialRefund;
use crate::refund::Refund;
use crate::sale::Sale;

/// What each kind of entry adds to the balance.
pub struct Totals;

impl Totals {
    pub fn net(entry: &dyn Entry) -> Result<Decimal> {
        // C#'s Signed((dynamic)entry): the binder picks the overload for the entry's own type;
        // a Note gets Signed(Entry).
        let any: &dyn Any = entry;
        if let Some(sale) = any.downcast_ref::<Sale>() {
            return sale.amount().checked_mul(Decimal::from(sale.units()));
        }
        if let Some(refund) = any.downcast_ref::<Refund>() {
            return Ok(-refund.amount());
        }
        if let Some(refund) = any.downcast_ref::<PartialRefund>() {
            return (-refund.amount()).checked_mul(refund.share());
        }
        Ok(Decimal::from(0))
    }
}

